update registros_tickets set gemini_raw = gemini_raw || '{"items": [{"descripcion": "apios", "cantidad": 2, "unidad": "kg", "monto": 70, "categoria": "Insumos Alimentos"}, {"descripcion": "zanahoria", "cantidad": 3, "unidad": "kg", "monto": 60, "categoria": "Insumos Alimentos"}, {"descripcion": "lechugas", "cantidad": 1, "unidad": "pz", "monto": 20, "categoria": "Insumos Alimentos"}, {"descripcion": "jitomates", "cantidad": 4, "unidad": "pz", "monto": 10, "categoria": "Insumos Alimentos"}], "fecha": "2026-08-06", "comercio": null, "monto_total": 160, "tipo_documento": "nota_a_mano", "confianza": "alta", "_revision": {"por": "Claude (revision contra foto)", "fecha": "2026-09-18", "veredicto": "corregir", "cambios": "Fecha 2026-08-16 -> 2026-08-06 (en DIA solo hay un 6). Importes corregidos: apios 20 -> 70 (es un 7 con barra; $35 por pieza, igual que en otras notas), lechuga 50 -> 20, 4o renglon 20 -> 10. Total 150 -> 160: 70+60+20+10 = 160, que cuadra con el total escrito. El 4o renglon no dice ''aguacates'', dice ''jitomates'' (misma letra de esta verduleria): 4 pz por $10."}}'::jsonb where id='8e0b1637-a243-4b18-b84f-dd6f25c6bf97' and estado='pendiente';
