update registros_tickets set gemini_raw = gemini_raw || '{"items": [{"descripcion": "GAS L.P.", "cantidad": 49, "unidad": "lt", "monto": 501.27, "categoria": "Gas"}], "fecha": "2026-08-22", "comercio": "GAS DE XALAPA S.A. DE C.V.", "monto_total": 501.27, "tipo_documento": "ticket", "confianza": "alta", "_revision": {"por": "Claude (revision contra foto)", "fecha": "2026-09-18", "veredicto": "corregir", "cambios": "Comercio: el encabezado esta cortado (''...XALAPA S.A. DE C.V.''). El RFC GXA550301BP3 corresponde a Gas de Xalapa, nombre que ya se usa en otros tickets. Lo demas cuadra: 49 L x $10.23 = $501.27, IVA incluido de 69.14. El precio por litro es normal, asi que la alerta precio_anomalo no aplica. La alerta posible_duplicado es falsa: el folio 4551 aparece una sola vez."}}'::jsonb where id='737fccf6-337f-49e1-bb5a-335d4dd37eb6' and estado='pendiente';
